function firstLastInstruction(){const seconds=Number(widget(node,"时长秒")?.value||5).toFixed(2);return `How the reference pictures align with the target video — Picture 1 (from Shot 1) aligns with the 0.00-second mark of the target video; Picture 2 (from Shot 1) aligns with the ${seconds}-second mark of the target video.`;}
function sharedBaseHelp(modeLabel,extra){return `<div class="focus"><strong>${modeLabel}主要内容写在哪里？</strong> 人物、场景、动作、表情、运镜、镜头时间、对白和画面内声音，都写在<strong>「正文」</strong>的 <code>integrated_multimodal_description:</code> 下面。<br><code>[Shot 1] Live-action, cinematic, the subject turns toward the camera as the camera slowly pushes in.</code></div>${extra}<div class="warning"><strong>不让角色读出提示词：</strong>写在「正文」下面：<br><code>No dialogue, narration, voiceover, or singing. The subject keeps their mouth closed throughout.</code><br><code>non_diegetic_music: N/A</code> 只表示无背景配乐，不代表禁止说话。</div>`;}
const refHelp=`<div class="focus"><strong>主要内容写在哪里？</strong> 人物动作、表情、运镜、镜头时间、对白和画面声音，主要由<strong>「分镜」</strong>控制。<br><code>detailed_description: [Shot 1] &lt;Subject 1&gt; turns toward the camera and says, &lt;d&gt;[Chinese] 你好！&lt;/d&gt;</code></div><div class="warning"><strong>不让角色读出提示词：</strong>写在「分镜」下面：<br><code>No dialogue, narration, voiceover, or singing. &lt;Subject 1&gt; keeps their mouth closed throughout.</code><br><code>non_diegetic_music: N/A</code> 只表示无背景配乐，不代表禁止说话。</div><dl><dt>模板</dt><dd>一次插入Ref2VA完整六段结构；只建骨架，不自动写内容。</dd><dt>定义</dt><dd>定义主体和来源。例：<code>&lt;Subject 1&gt; is the visual content referenced from &lt;Picture 1&gt;.</code></dd><dt>摘要</dt><dd>概括任务类型、目标视频和主要引用关系。</dd><dt>保留</dt><dd><code>fully_preserved</code>完整保留；<code>partially_preserved</code>部分保留；<code>attribute_transfer</code>属性迁移；<code>weak_reference</code>弱参考。</dd><dt>分镜</dt><dd>核心正文：按播放顺序写构图、位置、动作、灯光、运镜、声音和对白。</dd><dt>声景</dt><dd>全片环境声、动作声及非语言人声；对白仍写在分镜。</dd><dt>配乐</dt><dd>只有观众能听到的背景配乐；<code>N/A</code>表示无背景配乐。</dd></dl>`;
function baseHelp(mode){if(mode==="文生视频")return sharedBaseHelp("文生视频",`<div class="warning"><strong>文生规则：</strong>没有图片对齐指令，直接从「正文」开始完整描述开场、主体、场景和时间线。</div>`)+`<dl><dt>模板</dt><dd>插入文生三段官方骨架。</dd><dt>正文</dt><dd>从文字建立完整视听时间线。例：<code>[Shot 1] A woman enters a quiet café as the camera tracks left.</code></dd><dt>声景</dt><dd>环境声、动作声和非语言人声。</dd><dt>配乐</dt><dd>观众可听、角色听不到的背景音乐；默认<code>N/A</code>。</dd></dl>`;
if(mode==="图生视频")return sharedBaseHelp("图生视频",`<div class="warning"><strong>首帧规则：</strong><code>&lt;Picture 1&gt;</code>是0秒真实首帧。正文按“首帧状态 → 动作开始 → 连续发展 → 结果”写，并保持身份、服装、颜色和空间关系一致。</div>`)+`<dl><dt>模板</dt><dd>插入首帧固定对齐指令和三段骨架。</dd><dt>首帧</dt><dd>单独插入官方0秒首帧对齐指令。</dd><dt>正文</dt><dd>从首帧现状向后发展，不要只重复描述图片。</dd><dt>声景</dt><dd>环境声、动作声和非语言人声。</dd><dt>配乐</dt><dd>背景配乐；默认<code>N/A</code>。</dd></dl>`;
return sharedBaseHelp("首尾帧",`<div class="warning"><strong>首尾规则：</strong><code>Picture 1</code>是0秒首帧，<code>Picture 2</code>是视频结束尾帧。优先单镜头，正文写清“首帧状态 → 中间变化 → 差异逐步缩小 → 准确落到尾帧”。对齐按钮按当前时长自动写结束秒数。</div>`)+`<dl><dt>模板</dt><dd>按当前时长插入首尾帧对齐指令和三段骨架。</dd><dt>对齐</dt><dd>单独插入首图0秒、尾图结束时刻的官方对齐指令。</dd><dt>正文</dt><dd>描述两帧之间连续的动作、姿势、物体、构图和光线变化。</dd><dt>声景</dt><dd>环境声、动作声和非语言人声。</dd><dt>配乐</dt><dd>背景配乐；默认<code>N/A</code>。</dd></dl>`;}
