async function refreshNanFengModelCombos(){
  const response=await api.fetchApi("/nanfeng/v10/h3/refresh-models",{method:"POST",cache:"no-store"}),live=await readJsonResponse(response);
  if(!response.ok||!live.ok)throw new Error(live.error||`HTTP ${response.status}`);
  const defs=await api.getNodeDefs();
  for(const node of app.graph?._nodes||[]){
    if(!TARGETS.has(node.comfyClass||node.type))continue;
    const required=defs?.[node.comfyClass||node.type]?.input?.required||{};
    for(const name of ["模型","文本编码器","视频VAE","音频VAE",...Array.from({length:MAX_LORA_SLOTS},(_,i)=>`LoRA${i+1}`),"H3潜空间放大模型","H3二采LoRA"]){
      const values=live[name==="模型"?"模型":name.startsWith("LoRA")?"LoRA":name]||required?.[name]?.[0];if(!Array.isArray(values))continue;
      const w=widget(node,name);if(!w)continue;
      w.options||={};w.options.values=values;
      if(!values.includes(w.value)&&values.length)setWidget(node,name,values[0]);
      const select=node.__nfh3Root?.querySelector?.(`[data-widget-name="${name}"]`);
      if(select?.classList?.contains("nfh3-custom-select")){select.__nfh3SetValues?.(values);select.__nfh3Paint?.();}
      else if(select?.tagName==="SELECT"){
        select.replaceChildren();
        for(const item of values){const option=document.createElement("option");option.value=item;option.textContent=item;select.append(option);}
        select.value=w.value;
      }
    }
    node.__nfh3Render?.();node.setDirtyCanvas?.(true,true);
  }
}

